mapper.select:
SELECT NVL(SUM(r.register_revenue), 0) AS registerRevenue, -- 挂号收入 NVL(SUM(r.medical_revenue), 0) AS medicalRevenue, -- 医疗收入 NVL(SUM(r.register_revenue), 0) + NVL(SUM(r.medical_revenue), 0) + NVL(SUM(r.service_revenue), 0) AS outpatientRevenue, -- 门诊收入 NVL(SUM(r.service_revenue), 0) AS serviceRevenue -- 服务收入 FROM TR_REV_OV r INNER JOIN TR_DEPT_DICT d ON r.dept_code = d.dept_code WHERE r.stat_date BETWEEN #{startDate} AND #{endDate}
AND d.dept_code = #{deptCode}
AND d.dept_name LIKE '%' || #{deptName} || '%'

SELECT d.dept_name AS deptName, -- 科室名称 NVL(SUM(r.register_revenue), 0) AS registerRevenue, -- 挂号收入 NVL(SUM(r.medical_revenue), 0) AS medicalRevenue, -- 医疗收入 NVL(SUM(r.register_revenue), 0) + NVL(SUM(r.medical_revenue), 0) + NVL(SUM(r.service_revenue), 0) AS outpatientRevenue, -- 门诊收入 NVL(SUM(r.service_revenue), 0) AS serviceRevenue -- 服务收入 FROM TR_REV_OV r INNER JOIN TR_DEPT_DICT d ON r.dept_code = d.dept_code WHERE r.stat_date BETWEEN #{startDate} AND #{endDate}
AND d.dept_code = #{deptCode}
AND d.dept_name LIKE '%' || #{deptName} || '%'
GROUP BY d.dept_name ORDER BY NVL(SUM(r.register_revenue), 0) + NVL(SUM(r.medical_revenue), 0) + NVL(SUM(r.service_revenue), 0) DESC

SELECT r.doctor_name AS doctorName, -- 医生姓名 d.dept_name AS deptName, -- 科室名称 NVL(SUM(r.register_revenue), 0) AS registerRevenue, -- 挂号收入 NVL(SUM(r.medical_revenue), 0) AS medicalRevenue, -- 医疗收入 NVL(SUM(r.register_revenue), 0) + NVL(SUM(r.medical_revenue), 0) + NVL(SUM(r.service_revenue), 0) AS doctorBenefit, -- 医生效益(挂号+医疗+服务) NVL(SUM(r.service_revenue), 0) AS serviceRevenue -- 服务收入 FROM TR_REV_OV r INNER JOIN TR_DEPT_DICT d ON r.dept_code = d.dept_code WHERE r.stat_date BETWEEN #{startDate} AND #{endDate}
AND d.dept_code = #{deptCode}
AND d.dept_name LIKE '%' || #{deptName} || '%'
GROUP BY r.doctor_name, d.dept_name ORDER BY NVL(SUM(r.register_revenue), 0) + NVL(SUM(r.medical_revenue), 0) + NVL(SUM(r.service_revenue), 0) DESC
